def is_prefix_free(codes):
    words = list(codes.values())
    return not any(a != b and b.startswith(a) for a in words for b in words)
def decode(bits, codes):
    inv = {v: k for k, v in codes.items()}
    out, buf = [], ""
    for b in bits:
        buf += b
        if buf in inv:                  # 符号語が完成した瞬間に確定
            out.append(inv[buf]); buf = ""
    return "".join(out)
good = {"A": "0", "B": "10", "C": "110", "D": "111"}
bad = {"A": "0", "B": "01", "C": "11"}
print(is_prefix_free(good), is_prefix_free(bad))     # True False
print(decode("0101100111", good))                    # ABCAD
print("クラフト和:", sum(2 ** -len(c) for c in good.values()))   # 1.0

from fractions import Fraction as Fr
probs = {"a": Fr(6, 10), "b": Fr(3, 10), "c": Fr(1, 10)}
cum, c = {}, Fr(0)
for s, p in probs.items():
    cum[s] = (c, c + p); c += p                   # a:[0,.6) b:[.6,.9) c:[.9,1)
def encode(seq):
    lo, hi = Fr(0), Fr(1)
    for s in seq:
        w = hi - lo
        lo, hi = lo + w * cum[s][0], lo + w * cum[s][1]   # 区間を絞る
        print(s, float(lo), float(hi))
    # 区間内で最短の2進小数を探す
    k = 1
    while True:
        v = Fr(-(-lo.numerator * 2 ** k // lo.denominator), 2 ** k)   # ceil(lo*2^k)/2^k
        if v < hi:
            return format(int(v * 2 ** k), f"0{k}b")
        k += 1
print("符号:", encode("aab"))                     # 2進小数 0.01 → "01"

def lz77_encode(s, window=16, lookahead=8):
    i, out = 0, []
    while i < len(s):
        dist, length = 0, 0
        for j in range(max(0, i - window), i):          # 窓の中を探す
            k = 0
            while k < lookahead and i + k < len(s) - 1 and s[j + k] == s[i + k]:
                k += 1
            if k > length:
                dist, length = i - j, k
        out.append((dist, length, s[i + length]))       # (距離, 長さ, 次の文字)
        i += length + 1
    return out
def lz77_decode(tokens):
    s = []
    for d, l, c in tokens:
        for _ in range(l):
            s.append(s[-d])                             # d文字前から1文字ずつコピー
        s.append(c)
    return "".join(s)
t = lz77_encode("ABABABCABAB")
print(t, lz77_decode(t))

def lz78_encode(s):
    dic, out, w = {}, [], ""
    for c in s:
        if w + c in dic:
            w += c                               # まだ辞書にある → 伸ばす
        else:
            out.append((dic.get(w, 0), c))       # (最長一致の番号, 次の文字)
            dic[w + c] = len(dic) + 1            # 新しい単語を登録
            w = ""
    if w:
        out.append((dic[w], ""))
    return out, dic
def lz78_decode(tokens):
    words, s = [""], ""
    for i, c in tokens:
        w = words[i] + c; s += w; words.append(w)
    return s
t, d = lz78_encode("ABABABA")
print(t, d, lz78_decode(t))

def lzw_encode(s, alphabet="AB"):
    dic = {c: i for i, c in enumerate(alphabet)}   # 初期辞書：1文字すべて
    w, out = "", []
    for c in s:
        if w + c in dic:
            w += c
        else:
            out.append(dic[w])                      # 番号だけ出力
            dic[w + c] = len(dic)                   # w+c を登録
            w = c
    out.append(dic[w])
    return out
def lzw_decode(codes, alphabet="AB"):
    words = list(alphabet); w = words[codes[0]]; s = w
    for k in codes[1:]:
        e = words[k] if k < len(words) else w + w[0]   # まだ未登録の番号（特殊ケース）
        s += e; words.append(w + e[0]); w = e
    return s
c = lzw_encode("ABABABA"); print(c, lzw_decode(c))      # [0, 1, 2, 4] ABABABA
